/** static void Task_DoCardFlipTask(u8 taskId) */
export function Task_DoCardFlipTask(taskId: any): any {
  while(sTrainerCardFlipTasks[gTasks[taskId].tFlipState](gTasks[taskId]))
          ;
}

/** static bool8 Task_BeginCardFlip(struct Task *task) */
export function Task_BeginCardFlip(task: any): any {
  let i: any = null;

      HideBg(1);
      HideBg(3);
      ScanlineEffect_Stop();
      ScanlineEffect_Clear();
      for (i = 0; i < DISPLAY_HEIGHT; i++)
          gScanlineEffectRegBuffers[1][i] = 0;
      task.tFlipState++;
      return FALSE;
}

/** static bool8 Task_AnimateCardFlipDown(struct Task *task) */
export function Task_AnimateCardFlipDown(task: any): any {
  let cardHeight, r5, r10, cardTop, r6, var_24, cardBottom, _var;
      let i: any = null;

      sData.allowDMACopy = FALSE;
      if (task.tCardTop >= CARD_FLIP_Y)
          task.tCardTop = CARD_FLIP_Y;
      else
          task.tCardTop += 7;

      sData.cardTop = task.tCardTop;
      UpdateCardFlipRegs(task.tCardTop);

      cardTop = task.tCardTop;
      cardBottom = DISPLAY_HEIGHT - cardTop;
      cardHeight = cardBottom - cardTop;
      r6 = -cardTop << 16;
      r5 = (DISPLAY_HEIGHT << 16) / cardHeight;
      r5 -= 1 << 16;
      var_24 = r6;
      var_24 += r5 * cardHeight;
      r10 = r5 / cardHeight;
      r5 *= 2;

      for (i = 0; i < cardTop; i++)
          gScanlineEffectRegBuffers[0][i] = -i;
      for (; i < cardBottom; i++)
      {
          _var = r6 >> 16;
          r6 += r5;
          r5 -= r10;
          gScanlineEffectRegBuffers[0][i] = _var;
      }
      _var = var_24 >> 16;
      for (; i < DISPLAY_HEIGHT; i++)
          gScanlineEffectRegBuffers[0][i] = _var;

      sData.allowDMACopy = TRUE;
      if (task.tCardTop >= CARD_FLIP_Y)
          task.tFlipState++;

      return FALSE;
}

/** static bool8 Task_DrawFlippedCardSide(struct Task *task) */
export function Task_DrawFlippedCardSide(task: any): any {
  sData.allowDMACopy = FALSE;
      if (Overworld_IsRecvQueueAtMax() == TRUE)
          return FALSE;

      do
      {
          switch (sData.flipDrawState)
          {
          case 0:
              FillWindowPixelBuffer(WIN_CARD_TEXT, PIXEL_FILL(0));
              FillBgTilemapBufferRect_Palette0(3, 0, 0, 0, 0x20, 0x20);
              break;
          case 1:
              if (!sData.onBack)
              {
                  if (!PrintAllOnCardBack())
                      return FALSE;
              }
              else
              {
                  if (!PrintAllOnCardFront())
                      return FALSE;
              }
              break;
          case 2:
              if (!sData.onBack)
                  DrawCardFrontOrBack(sData.backTilemap);
              else
                  DrawTrainerCardWindow(WIN_CARD_TEXT);
              break;
          case 3:
              if (!sData.onBack)
                  DrawCardBackStats();
              else
                  FillWindowPixelBuffer(WIN_TRAINER_PIC, PIXEL_FILL(0));
              break;
          case 4:
              if (sData.onBack)
                  CreateTrainerCardTrainerPic();
              break;
          default:
              task.tFlipState++;
              sData.allowDMACopy = TRUE;
              sData.flipDrawState = 0;
              return FALSE;
          }
          sData.flipDrawState++;
      } while (gReceivedRemoteLinkPlayers == 0);

      return FALSE;
}

/** static bool8 Task_SetCardFlipped(struct Task *task) */
export function Task_SetCardFlipped(task: any): any {
  sData.allowDMACopy = FALSE;

       
      if (sData.onBack)
      {
          DrawTrainerCardWindow(WIN_TRAINER_PIC);
          DrawCardScreenBackground(sData.bgTilemap);
          DrawCardFrontOrBack(sData.frontTilemap);
          DrawStarsAndBadgesOnCard();
      }
      DrawTrainerCardWindow(WIN_CARD_TEXT);
      sData.onBack ^= 1;
      task.tFlipState++;
      sData.allowDMACopy = TRUE;
      PlaySE(SE_RG_CARD_FLIPPING);
      return FALSE;
}

/** static bool8 Task_AnimateCardFlipUp(struct Task *task) */
export function Task_AnimateCardFlipUp(task: any): any {
  let cardHeight, r5, r10, cardTop, r6, var_24, cardBottom, _var;
      let i: any = null;

      sData.allowDMACopy = FALSE;
      if (task.tCardTop <= 5)
          task.tCardTop = 0;
      else
          task.tCardTop -= 5;

      sData.cardTop = task.tCardTop;
      UpdateCardFlipRegs(task.tCardTop);

      cardTop = task.tCardTop;
      cardBottom = DISPLAY_HEIGHT - cardTop;
      cardHeight = cardBottom - cardTop;
      r6 = -cardTop << 16;
      r5 = (DISPLAY_HEIGHT << 16) / cardHeight;
      r5 -= 1 << 16;
      var_24 = r6;
      var_24 += r5 * cardHeight;
      r10 = r5 / cardHeight;
      r5 /= 2;

      for (i = 0; i < cardTop; i++)
          gScanlineEffectRegBuffers[0][i] = -i;
      for (; i < cardBottom; i++)
      {
          _var = r6 >> 16;
          r6 += r5;
          r5 += r10;
          gScanlineEffectRegBuffers[0][i] = _var;
      }
      _var = var_24 >> 16;
      for (; i < DISPLAY_HEIGHT; i++)
          gScanlineEffectRegBuffers[0][i] = _var;

      sData.allowDMACopy = TRUE;
      if (task.tCardTop <= 0)
          task.tFlipState++;

      return FALSE;
}

/** static bool8 Task_EndCardFlip(struct Task *task) */
export function Task_EndCardFlip(task: any): any {
  ShowBg(1);
      ShowBg(3);
      SetHBlankCallback(NULL);
      DestroyTask(FindTaskIdByFunc(Task_DoCardFlipTask));
      return FALSE;
}

/** void ShowPlayerTrainerCard(void (*callback)(void)) */
export function ShowPlayerTrainerCard(callback: any): any {
  sData = AllocZeroed(0);
      sData.callback2 = callback;
      if (callback == CB2_ReshowFrontierPass)
          sData.blendColor = RGB_WHITE;
      else
          sData.blendColor = RGB_BLACK;

      if (InUnionRoom() == TRUE)
          sData.isLink = TRUE;
      else
          sData.isLink = FALSE;

      sData.language = GAME_LANGUAGE;
      TrainerCard_GenerateCardForPlayer(sData.trainerCard);
      SetMainCallback2(CB2_InitTrainerCard);
}

/** void ShowTrainerCardInLink(u8 cardId, void (*callback)(void)) */
export function ShowTrainerCardInLink(cardId: any, callback: any): any {
  sData = AllocZeroed(0);
      sData.callback2 = callback;
      sData.isLink = TRUE;
      sData.trainerCard = gTrainerCards[cardId];
      sData.language = gLinkPlayers[cardId].language;
      SetMainCallback2(CB2_InitTrainerCard);
}

/** static void InitTrainerCardData(void) */
export function InitTrainerCardData(): any {
  let i: any = null;

      sData.mainState = 0;
      sData.timeColonBlinkTimer = gSaveBlock2Ptr.playTimeVBlanks;
      sData.timeColonInvisible = FALSE;
      sData.onBack = FALSE;
      sData.flipBlendY = 0;
      sData.cardType = GetSetCardType();
      for (i = 0; i < TRAINER_CARD_PROFILE_LENGTH; i++)
          CopyEasyChatWord(sData.easyChatProfile[i], sData.trainerCard.easyChatProfile[i]);
}

/** static u8 GetSetCardType(void) */
export function GetSetCardType(): any {
  if (sData == NULL)
      {
          if (gGameVersion == VERSION_FIRE_RED || gGameVersion == VERSION_LEAF_GREEN)
              return CARD_TYPE_FRLG;
          else if (gGameVersion == VERSION_EMERALD)
              return CARD_TYPE_EMERALD;
          else
              return CARD_TYPE_RS;
      }
      else
      {
          if (sData.trainerCard.version == VERSION_FIRE_RED || sData.trainerCard.version == VERSION_LEAF_GREEN)
          {
              sData.isHoenn = FALSE;
              return CARD_TYPE_FRLG;
          }
          else if (sData.trainerCard.version == VERSION_EMERALD)
          {
              sData.isHoenn = TRUE;
              return CARD_TYPE_EMERALD;
          }
          else
          {
              sData.isHoenn = TRUE;
              return CARD_TYPE_RS;
          }
      }
}

/** static u8 VersionToCardType(u8 version) */
export function VersionToCardType(version: any): any {
  if (version == VERSION_FIRE_RED || version == VERSION_LEAF_GREEN)
          return CARD_TYPE_FRLG;
      else if (version == VERSION_EMERALD)
          return CARD_TYPE_EMERALD;
      else
          return CARD_TYPE_RS;
}

/** static void CreateTrainerCardTrainerPic(void) */
export function CreateTrainerCardTrainerPic(): any {
  if (InUnionRoom() == TRUE && gReceivedRemoteLinkPlayers == 1)
      {
          CreateTrainerCardTrainerPicSprite(FacilityClassToPicIndex(sData.trainerCard.unionRoomClass),
                      TRUE,
                      sTrainerPicOffset[sData.isHoenn][sData.trainerCard.gender][0],
                      sTrainerPicOffset[sData.isHoenn][sData.trainerCard.gender][1],
                      8,
                      WIN_TRAINER_PIC);
      }
      else
      {
          CreateTrainerCardTrainerPicSprite(FacilityClassToPicIndex(sTrainerPicFacilityClass[sData.cardType][sData.trainerCard.gender]),
                      TRUE,
                      sTrainerPicOffset[sData.isHoenn][sData.trainerCard.gender][0],
                      sTrainerPicOffset[sData.isHoenn][sData.trainerCard.gender][1],
                      8,
                      WIN_TRAINER_PIC);
      }
}

